def exist(board: List[List[str]], word: str) -> bool:
    rows = len(board)
    cols = len(board[0])

    def search_from(r, c, index, visited):
        if index == len(word):
            return True
        if r < 0 or r >= rows or c < 0 or c >= cols:
            return False
        if (r, c) in visited:
            return False
        if board[r][c] != word[index]:
            return False

        visited.add((r, c))
        found = (
            search_from(r + 1, c, index + 1, visited) or
            search_from(r - 1, c, index + 1, visited) or
            search_from(r, c + 1, index + 1, visited) or
            search_from(r, c - 1, index + 1, visited)
        )
        visited.remove((r, c))
        return found

    all_paths = []
    for r in range(rows):
        for c in range(cols):
            if search_from(r, c, 0, set()):
                return True
    return False

